// 转换为二进制字符串
string toBinary(int num) {
    if (num == 0) return "0";
    string res;
    while (num > 0) {
        res = (char)('0' + (num % 2)) + res;
        num /= 2;
    }
    return res;
}
​
int main() {
    int n;
    cin >> n;
    string s = "0" + toBinary(n);


    int m = s.size();
    int i = m - 1;

    int count = 0;
    for (; i >= 0; i--) {
        if (s[i] == '1' && s[i - 1] == '0') {
            s[i] = '0';
            s[i - 1] = '1';
            break;
        }
        // 记录交换之前出现的1的数量
        if (s[i] == '1') {
            count++;
        }
    }
    // 将交换之前出现的1全部移到末尾去
    for (int j = i + 1; j < m; j++) {
        if (m - j> count) {
            s[j] = '0';
        } else {
            s[j] = '1';
        } 
    }
    int res = stol(s, nullptr, 2);
    cout << res << endl;
    return 0; 
}

