import java.util.Scanner;
​
public class Main {
    // 转换为二进制字符串
    static String toBinary(int num) {
        if (num == 0) return "0";
        StringBuilder res = new StringBuilder();
        while (num > 0) {
            res.insert(0, num % 2);
            num /= 2;
        }
        return res.toString();
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        String s = "0" + toBinary(n); // 补前导 0
​
        char[] chars = s.toCharArray();
        int m = chars.length;
        int i = m - 1, count = 0;
​
        for (; i >= 1; i--) {
            if (chars[i] == '1' && chars[i - 1] == '0') {
                chars[i] = '0';
                chars[i - 1] = '1';
                break;
            }
            if (chars[i] == '1') count++;
        }
​
        for (int j = i + 1; j < m; j++) {
            chars[j] = (m - j > count) ? '0' : '1';
        }
​
        long res = Long.parseLong(new String(chars), 2);
        System.out.println(res);
    }
}
