        if chars[i] == '1' && chars[i-1] == '0' {
            chars[i] = '0'
            chars[i-1] = '1'
            break
        }
        if chars[i] == '1' {
            count++
        }
        i--
    }
    // 交换之前的1移动道末尾
    for j := i + 1; j < m; j++ {
        if m-j > count {
            chars[j] = '0'
        } else {
            chars[j] = '1'
        }
    }
​
